const {test}=require('node:test'),assert=require('node:assert/strict'),fs=require('node:fs'),vm=require('node:vm');
function setup(){const c={window:{}};vm.createContext(c);for(const f of ['white-orchard.js','map-data.js','diagrams-data.js','exploration-data.js','progression-data.js','progression-engine.js','departure.js'])vm.runInContext(fs.readFileSync(f,'utf8'),c);const w=c.window,{tasks,hubs}=w.PHOENIX_ROUTE,engine=w.createPhoenixProgress(w.PHOENIX_PROGRESS_DATA,tasks,hubs),state={progress:engine.init(),completed:{}};return {w,tasks,engine,state,build:()=>w.PhoenixDeparture.build({state,engine,tasks}),summary:v=>w.PhoenixDeparture.summaryText(v)};}
test('fresh records: all four items unknown, skull first, zero open shown',()=>{const x=setup(),v=x.build();assert.equal(v.unknowns.length,4);assert.equal(v.knownOpen.length,0);assert.equal(v.ordered[0].id,'poi-4');assert.ok(v.unknowns.every(u=>u.status.includes('check in game')));assert.match(x.summary(v),/^0 known open risks · 4 unknown items/);assert.ok(!/All 4 items recorded complete/.test(x.summary(v)));});
test('cutoff-passed skull remains unknown, not failed, and not warning-eligible',()=>{const x=setup();x.state.progress.manual.griffin=true;const v=x.build();assert.equal(v.skull.kind,'cutoff-unknown');assert.equal(v.skull.failed,false);assert.ok(v.unknowns.some(u=>u.id==='poi-4'));assert.ok(!v.warningEligible.some(r=>r.id==='poi-4'));});
test('explicit failed stays failed; unavailable is unknown not failed',()=>{const x=setup();x.state.progress.failed['q-death']=true;const v=x.build();assert.ok(v.failed.some(f=>f.id==='q-death'));assert.ok(v.ordered.every(r=>r.kind!=='unavailable'||r.unknown));assert.ok(!v.warningEligible.some(r=>r.id==='q-death'));});
test('completed collapse group preserves cutoff order',()=>{const x=setup();x.state.completed['poi-4']=true;x.state.progress.legacy['q-firestarter']=true;const v=x.build();assert.equal(v.completed.map(c=>c.id).join(','),'poi-4,q-firestarter');});
test('no false all-clear when unknowns or failed remain',()=>{const x=setup();x.state.progress.failed['q-missing']=true;const v=x.build();assert.ok(v.unknowns.length>0||v.failed.length>0);assert.ok(v.knownOpen.length===0);assert.ok(!/All 4 items recorded complete/.test(x.summary(v)));});
test('mixed case shows separate counts including zeros and no confirmation',()=>{const x=setup();x.state.progress.legacy['q-firestarter']=true;x.state.progress.failed['q-missing']=true;const v=x.build(),s=x.summary(v);assert.match(s,/0 known open risks/);assert.match(s,/unknown item/);assert.match(s,/recorded failed/);assert.match(s,/recorded complete/);assert.ok(!/All 4 items recorded complete/.test(s));});
test('all four positively recorded complete shows confirmation',()=>{const x=setup();x.state.completed['poi-4']=true;x.state.progress.legacy['q-firestarter']=true;x.state.progress.legacy['q-missing']=true;x.state.progress.legacy['q-death']=true;const v=x.build(),s=x.summary(v);assert.equal(v.completed.length,4);assert.equal(v.unknowns.length,0);assert.equal(v.failed.length,0);assert.match(s,/0 known open risks · 0 unknown items/);assert.match(s,/All 4 items recorded complete/);});
test('failed with no open items shows counts and no confirmation',()=>{const x=setup();x.state.progress.failed['q-firestarter']=true;x.state.progress.failed['q-missing']=true;x.state.progress.failed['q-death']=true;x.state.completed['poi-4']=true;const v=x.build(),s=x.summary(v);assert.equal(v.knownOpen.length,0);assert.equal(v.failed.length,3);assert.match(s,/0 known open risks/);assert.match(s,/recorded failed/);assert.ok(!/All 4 items recorded complete/.test(s));});
